'use client';

import { useRouter, useSearchParams } from 'next/navigation';
import {
  createContext, memo, use, useCallback, useEffect, useMemo, useRef, useState,
} from 'react';
import { toast } from 'react-toastify';
import { useLatest } from 'react-use';

import SaveChoiceModal from './SaveChoiceModal';
import useApiMethods from './useApiMethods';
import useEditableState from './useEditableState';
import usePreferences from './usePreferences';
import usePusher, { forgetOwnSave } from './usePusher';

import type { MutableRefObject, PropsWithChildren } from 'react';
import type { Id } from 'react-toastify';
import type { RecentMessageData } from '~/server/api/utils/shapes';
import type { ContentLossOption } from '~/utils';

import { useGuild } from '~/providers/GuildProvider';
import { useNavigationGuard } from '~/providers/NavigationGuardProvider';
import { useWebhook } from '~/providers/WebhookProvider';
import {
  isApiMessage, makeEditable, stripKeys, timestampFromSnowflake, typedDeepEqual,
} from '~/utils';
import { api } from '~/utils/api';
import copyIntroMessage from '~/utils/copyIntroMessage';
import { useParsePathname, useToggleState } from '~/utils/hooks';
import {
  readDrafts, removeDraft, removeRouteZeroDraft, routeZeroDraftFor, sameJson, tabId, writeDraft,
  writeRouteZeroDraft,
} from '~/utils/messageDrafts';
import { detectMessageMode } from '~/utils/messageMode';

function getMessage(
  message: ApiMessage,
  ignoreLocalRef: MutableRefObject<boolean>,
) {
  const draft = readDrafts()[message.id];

  if (!ignoreLocalRef.current && draft && draft.editedAt > message.updatedAt) {
    return {
      ...message, data: draft.data, name: draft.name, updatedAt: draft.editedAt,
    };
  }

  return message;
}

function storedToActive(stored: StoredMessage): Omit<ApiMessage, 'id' | 'createdAt' | 'previewImageNonce'> {
  const messageTimestamp = timestampFromSnowflake(stored.messageId);
  return {
    guildId: stored.guildId,
    data: stored.data,
    name: 'New Message',
    updatedAt: messageTimestamp,
    recentMessageId: stored.messageId ?? null,
    recentWebhookId: stored.webhookId ?? null,
    recentThreadId: stored.threadId ?? null,
  };
}

type State = {
  message: null | ActiveMessage;
  isLoading: boolean;
  messageError: null | TRPCQueryError;
  isSaving: boolean;
  hasChanged: boolean;
  savedMessage: ActiveMessage | null;
  showHelp: boolean;
  editableState: EditableState;
  visualStyle: 'cozy' | 'compact';
  toggleHelp: () => void;
  closeHelp: () => void;
  updateMessage: (arg: Partial<ActiveMessage> | Partial<ApiMessage>) => void;
  saveMessage: (overrideMessage?: Partial<ActiveMessage>, silent?: boolean) => void;
  pendingSaveChoice: null | {
    draft: ActiveMessage;
    options: readonly ContentLossOption[];
  };
  commitSaveChoice: (chosenOption: ContentLossOption) => void;
  cancelSaveChoice: VoidFunction;
  updateRecentMessageData: (arg: RecentMessageData) => void;
  reloadMessage: () => void;
  toggleVisualStyle: () => void;
  toggleSuppressPings: () => void;
};
export const Context = createContext<State | null>(null);
export const useMessage = () => {
  const context = use(Context);

  if (context === null) {
    throw new Error('UnsavedWarning components must be wrapped in <UnsavedWarning />');
  }

  return context;
};

function isSameMessage(destination: string, messageId: string) {
  const url = new URL(destination, window.location.href);
  return url.origin === window.location.origin
    && /^\/message\/m\/(\d+)\/(?:edit|send)\/?$/.exec(url.pathname)?.[1] === messageId;
}

function useValue() {
  const router = useRouter();
  const { messageId: paramMessageId = '' } = useParsePathname();
  const searchParams = useSearchParams();
  const { webhooks, setGuildId } = useGuild();
  const { setThreadId, setSelectedWebhook } = useWebhook();
  const loadedRef = useRef<null | ActiveMessage>(null);

  const [message, setMessage] = useState<null | ActiveMessage>(null);
  const [savedMessage, setSavedMessage] = useState<null | ActiveMessage>(message);
  const [showHelp, { toggle: toggleHelp, setFalse: closeHelp }] = useToggleState();
  const [visualStyle, { toggle: toggleVisualStyle }] = useToggleState();

  const hasChanged = useMemo(
    () => !typedDeepEqual(savedMessage?.data, message?.data),
    [message?.data, savedMessage],
  );

  const { register } = useNavigationGuard();
  useEffect(
    () => register((destination) => hasChanged && !isSameMessage(destination, paramMessageId)),
    [register, hasChanged, paramMessageId],
  );

  usePreferences(message);

  const editableState = useEditableState();

  function detectMode(msg: ActiveMessage | null) {
    const mode = detectMessageMode(msg);
    if (mode) editableState.setMessageMode(mode);
  }

  const messageCode = searchParams?.get('code') ?? '';
  const {
    isFetching: isCodeMessageFetching,
    data: codeMessage, error: codeMessageError,
  } = api.message.getFromCode.useQuery({ code: messageCode }, {
    enabled: !!(paramMessageId === '0' && messageCode),
    staleTime: Infinity,
    refetchOnWindowFocus: false,
  });

  // Replaces onSuccess/onError callbacks removed in RQ5
  useEffect(() => {
    if (codeMessage) {
      const tmp = makeEditable(storedToActive(codeMessage));
      writeRouteZeroDraft(tmp);
      loadedRef.current = tmp;
      setMessage(tmp);
      setSavedMessage(tmp);
      detectMode(tmp);
    }
  }, [codeMessage]);

  useEffect(() => {
    if (codeMessageError) toast.error(codeMessageError.message);
  }, [codeMessageError]);

  useEffect(() => {
    if (paramMessageId === '0' && !messageCode) {
      const draft = routeZeroDraftFor(tabId());
      const tmp = draft
        ? makeEditable({ name: draft.name, data: draft.data, updatedAt: draft.editedAt })
        : copyIntroMessage();
      loadedRef.current = tmp;
      setMessage(tmp);
      setSavedMessage(tmp);
      detectMode(tmp);
    }
  }, [paramMessageId]);

  useEffect(() => {
    if (message?.guildId) setGuildId(message.guildId);
  }, [message && isApiMessage(message) && message.guildId]);

  useEffect(() => {
    if (!message?.name || message === loadedRef.current) return;
    const name = savedMessage?.name ?? message.name;
    if (!message.id) {
      writeRouteZeroDraft({ ...message, name });
    } else if (typedDeepEqual(savedMessage?.data, message.data)) {
      removeDraft(message.id);
    } else {
      writeDraft(message.id, { data: message.data, name, editedAt: Date.now() });
    }
  }, [message]);

  const messageRef = useLatest<null | ActiveMessage>(message);
  useEffect(() => {
    if (message?.recentWebhookId) {
      const webhook = webhooks.find((wh) => wh.id === message.recentWebhookId);
      if (webhook) {
        setSelectedWebhook(webhook);
        // setUrl(constructWebhookUrl(webhook, message.recentMessageId, message.recentThreadId));
      }
      if (message?.recentThreadId) {
        setThreadId(message.recentThreadId);
      }
    }
  }, [webhooks, message?.recentWebhookId, message?.recentThreadId]);

  const ignoreLocalRef = useRef(false);
  const {
    isLoading, error: messageError, refetch, data: fetchedMessage, fetchStatus: messageFetchStatus,
  } = api.message.getOne.useQuery(paramMessageId, {
    enabled: paramMessageId !== '0',
    staleTime: Infinity,
    refetchOnWindowFocus: false,
    refetchOnMount: 'always',
  });

  // Replaces onSuccess callback removed in RQ5
  useEffect(() => {
    if (fetchedMessage) {
      const mostRecent = getMessage(fetchedMessage, ignoreLocalRef);
      if (mostRecent === fetchedMessage) {
        const tmp = makeEditable(fetchedMessage);
        removeDraft(fetchedMessage.id);
        loadedRef.current = tmp;
        setMessage(tmp);
        setSavedMessage(tmp);
        detectMode(tmp);
      } else {
        const tmp = makeEditable(mostRecent);
        loadedRef.current = tmp;
        setMessage(tmp);
        setSavedMessage(makeEditable(fetchedMessage));
        detectMode(tmp);
      }
      ignoreLocalRef.current = false;
    }
  }, [fetchedMessage]);

  // Replaces onSettled callback removed in RQ5 — reset ignoreLocalRef
  // when fetching completes (fetchStatus toggles on every fetch cycle,
  // unlike status which stays 'success' on refetches with cached data).
  useEffect(() => {
    if (messageFetchStatus === 'idle' && ignoreLocalRef.current) {
      ignoreLocalRef.current = false;
    }
  }, [messageFetchStatus]);

  const ownSaveRecordsRef = useRef<string[]>([]);
  const toastIdRef = useRef<null | Id>(-1);
  const { mutate: upsertMessage, isPending: isSaving } = api.message.upsert.useMutation({
    onMutate: () => {
      if (toastIdRef.current !== null) {
        toastIdRef.current = toast.loading('Saving message...');
      }
    },
    onSuccess: (msg, { message: sent }) => {
      if (message?.id) {
        removeDraft(message.id, (draft) => sameJson(stripKeys({ name: draft.name, data: draft.data }).data, sent.data));
      } else {
        removeRouteZeroDraft(message?.data as ActiveMessage['data']);
      }
      if (toastIdRef.current !== null) {
        if (msg.id !== message?.id) {
          router.replace(`/message/m/${msg.id}/edit`);
        } else {
          setSavedMessage(message);
          toast.update(toastIdRef.current, {
            type: 'success',
            render: 'Message saved!',
            isLoading: false,
            autoClose: null,
          });
        }
      } else {
        toastIdRef.current = -1;
      }
    },
    onError: (_error, { message: sent }) => {
      forgetOwnSave(ownSaveRecordsRef, sent);
      if (toastIdRef.current !== null) {
        toast.update(toastIdRef.current, {
          type: 'error',
          render: 'Error. Failed to save message. Please try again.',
          isLoading: false,
          autoClose: null,
        });
      } else {
        toastIdRef.current = -1;
      }
    },
  });

  const trpc = api.useUtils();
  const { mutate: updateRecentMessageData } = api.message.updateRecentMessageData.useMutation({
    onSuccess() {
      void trpc.message.getOne.invalidate();
    },
  });

  const {
    updateMessage, saveMessage, reloadMessage,
    pendingSaveChoice, commitSaveChoice, cancelSaveChoice,
  } = useApiMethods(
    messageRef,
    ignoreLocalRef,
    setMessage,
    refetch,
    upsertMessage,
    editableState.setMessageMode,
    ownSaveRecordsRef,
  );

  usePusher(messageRef, reloadMessage, hasChanged, ownSaveRecordsRef);

  const toggleSuppressPings = useCallback(() => {
    if (message) {
      updateMessage({
        data: {
          ...message.data,
          allowed_mentions: message.data.allowed_mentions ? undefined : { parse: [] },
        },
      });
    }
  }, [message]);

  const state: State = {
    message,
    isLoading: paramMessageId !== '0' && (isLoading || isCodeMessageFetching),
    messageError,
    isSaving,
    hasChanged,
    savedMessage,
    showHelp,
    editableState,
    visualStyle: visualStyle ? 'compact' : 'cozy',
    toggleHelp,
    closeHelp,
    toggleVisualStyle,
    updateMessage,
    saveMessage,
    pendingSaveChoice,
    commitSaveChoice,
    cancelSaveChoice,
    updateRecentMessageData,
    reloadMessage,
    toggleSuppressPings,
  };

  return useMemo(() => state, Object.values(state));
}

const Provider = memo(({ children }: PropsWithChildren) => {
  const value = useValue();
  return (
    <Context.Provider value={value}>
      {children}
      {value.pendingSaveChoice ? (
        <SaveChoiceModal
          options={value.pendingSaveChoice.options}
          onChoose={value.commitSaveChoice}
          onCancel={value.cancelSaveChoice}
        />
      ) : null}
    </Context.Provider>
  );
});
Provider.displayName = 'ConfirmationProvider';
export default Provider;
